+public class UnwrapTest
+{
+    @Test
+    public void testUnwrapConnection() throws SQLException
+    {
+        HikariConfig config = new HikariConfig();
+        config.setMinimumPoolSize(1);
+        config.setMaximumPoolSize(1);
+        config.setAcquireIncrement(1);
