+    @Test
+    public void test_context_value_filter_not_effected () {
+        List<Object> params = new ArrayList<Object>();
+        Map data = new HashMap();
+        data.put("name", "ace");
+        params.add(data);
+        //fail Actual   :[{"name":"ace"}]
+        Assert.assertEquals("[{\"name\":\"mark-ace\"}]", JSON.toJSONString(params,
+                        new SerializeFilter[]{
+                                contextValueFilter
+                        })
+        );
+
+    }
