+        Map data = new HashMap();
+        data.put("name", "ace");
+        params.add(data);
+        //success
+        Assert.assertEquals("[{\"name\":\"mark-ace\"}]", JSON.toJSONString(params,
+                        new SerializeFilter[]{
+                                contextValueFilter,
+                                valueFilter
+                        })
+        );
+    }
