+        assertFalse(SentenceValidator.isSentence(nmea));
+
+        nmea="$GPRMC,142312.000,V,,,,,,,080514,,*20\n\r";
+        assertFalse(SentenceValidator.isSentence(nmea));
+
+        nmea="$GPRMC,142312.000,V,,,,,,,080514,,*20\r";
+        assertFalse(SentenceValidator.isSentence(nmea));
+
+        nmea="$GPRMC,142312.000,V,,,,,,,080514,,*20\n";
+        assertFalse(SentenceValidator.isSentence(nmea));
+
+        nmea="$GPRMC,142312.000,V,,,,,,,080514,,*20xy";
+        assertFalse(SentenceValidator.isSentence(nmea));
+
