+        public String getName() {
+            return templateId;
+        }
+    }
+
+    public static class FloorV2 implements Area {
+        public List<Area> children;
+
+        public String type;
+
+        public String templateId;
+
+        public String getName() {
+            return templateId;
+        }
+    }
+}

