+		Dao<EntityWithCustomTypeId, EntityId> dao = createDao(EntityWithCustomTypeId.class, true);
+
+		EntityWithCustomTypeId data = new EntityWithCustomTypeId();
+		data.id = EntityId.entityId("generated_id_from_factory");
