+        if (Modifier.isAbstract(superClass.getModifiers())) {
+            Class<?>[] types = method.getParameterTypes();
+
+            for (Method interfaceMethod : superClass.getMethods()) {
+                Class<?>[] interfaceTypes = interfaceMethod.getParameterTypes();
