+      return "Good Bye " + whom;
+    }
+
+    @Get("/add/:left/:right")
+    public int add(int left, int right) {
+      return left + right;
+    }
+
+    @Get("/void")
+    public void empty() {
+    }
+
+    @Get("/voidJson")
+    @Produces("application/json")
+    public void emptyJson() {
+    }
+
+    @Get("/1variable")
