+		for (int x = 0; x < a.getWidth(); x++)
+			for (int y = 0; y < a.getHeight(); y++)
+			{
+				int a_argb = a.getRGB(x, y);
+				int b_argb = b.getRGB(x, y);
+				if (a_argb != b_argb)
+				{
+					if (calculateARGBDistance(a_argb, b_argb) <= tolerance)
+						continue; // ignore.
+				}
+				if (a_argb != b_argb)
