+	private int calculateARGBDistance(int a, int b)
+	{
+		int aAlpha = 0xff & (a >> 24);
+		int aRed = 0xff & (a >> 16);
+		int aGreen = 0xff & (a >> 8);
+		int aBlue = 0xff & (a >> 0);
+		int bAlpha = 0xff & (b >> 24);
+		int bRed = 0xff & (b >> 16);
+		int bGreen = 0xff & (b >> 8);
+		int bBlue = 0xff & (b >> 0);
+		int diff = Math.abs(aAlpha - bAlpha) + Math.abs(aRed - bRed)
+				+ Math.abs(aGreen - bGreen) + Math.abs(aBlue - bBlue);
+		return diff;
+
+	}
