+
+        TestBean tb12 = jo.toJavaObject(TestBean.class);
+        assertEquals('c', tb12.getC());
+
+        TestBean2 tb22 = jo.toJavaObject(TestBean2.class);
+        assertEquals('c', tb22.getC().charValue());
+    }
