+
+  @AfterClass public static void afterClass() {
+    assertTrue(beforeClassCalled);
+    assertFalse(afterClassCalled);
+    afterClassCalled = true;
+  }
+
+  @Test public void testSnackIsSet() {
+    assertTrue(beforeClassCalled);
+    assertFalse(afterClassCalled);
+    assertNotNull(snack);
+  }
+}
