+  @ClassRule public static TestRule rule = new ExternalResource() {
+    @Override protected void before() throws Throwable {
+      assertFalse(beforeCalled);
+      beforeCalled = true;
+    }
+
+    @Override protected void after() {
+      assertTrue(beforeCalled);
