+                    @JSONField(name = "name") String name,
+                    @JSONField(name = "pinyin") String pinyin) {
+            this.code = code;
+            this.name = name;
+            this.pinyin = pinyin;
+        }
+    }
+
+    public static interface Parcelable {
+
+    }
+}

